INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be1d8de8-2a02-4647-b80f-41b44a62e712', '274aa5df-d415-4092-8772-da1b4d527e4c', 0, 'Because those files require special file permissions that only validate can set');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60e39e1e-84c7-46cd-9921-bec44579dd2b', '274aa5df-d415-4092-8772-da1b4d527e4c', 1, 'Because a syntax error in those files can lock out access or break a critical service, so checking with the file''s own native validator (e.g. visudo -cf, sshd -t) before committing the change is much safer than discovering the error after the fact');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('34eba7e7-65a2-47ea-b42d-7a6bd2bae3a2', '274aa5df-d415-4092-8772-da1b4d527e4c', 2, 'Because Ansible refuses to template those specific filenames without validate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('21b2c40c-2f8c-43e5-86f1-9c0b34848971', '274aa5df-d415-4092-8772-da1b4d527e4c', 3, 'Because those files must be templated with copy instead of template unless validate is set');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6753ee9-30f3-49ca-b9c7-e2940b72a9ee', 'f896c2be-6ffe-4c48-a225-89c7b1ca09c8', 0, 'Whether the task follows up with a handler notification');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('36f68ac5-682a-4bbb-b4cd-377589d3fed8', 'f896c2be-6ffe-4c48-a225-89c7b1ca09c8', 1, 'Whether the module follows a symbolic link at dest (writing through it to the link''s target) rather than replacing the symlink itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8dae0d70-5b2c-4e7b-b3ac-d774d80b454e', 'f896c2be-6ffe-4c48-a225-89c7b1ca09c8', 2, 'Whether the src template file is allowed to reference other templates');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e93c0ad0-b3d3-4b07-aea8-4dbd48d6c335', 'f896c2be-6ffe-4c48-a225-89c7b1ca09c8', 3, 'Whether Ansible follows redirects when src is a URL');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7cb11a1f-40e2-4c5f-b727-7cd127d223fa', 'ca8574ff-bf4c-4315-bf82-5aea4d831c68', 0, 'It sets the encoding used to read the src template on the control node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0dab9299-d316-43d4-a2b1-f118169d567f', 'ca8574ff-bf4c-4315-bf82-5aea4d831c68', 1, 'It sets the character encoding used when writing the rendered output file, independent of the (always UTF-8) source template encoding');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('297e06fa-7f38-401b-aacc-b465164829cf', 'ca8574ff-bf4c-4315-bf82-5aea4d831c68', 2, 'It compresses the output file');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4c0cb6b-cb34-4175-b26a-b5973cd5e763', 'ca8574ff-bf4c-4315-bf82-5aea4d831c68', 3, 'It has no effect and is deprecated');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('686fc137-1da5-46eb-ad7d-61612276cf53', '64c26096-e3e3-4664-8e9c-4ad5f5dab153', 0, 'mode and force');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ee9e67fa-9c59-42d8-8c9c-c00ae5becf89', '64c26096-e3e3-4664-8e9c-4ad5f5dab153', 1, 'variable_start_string and variable_end_string (along with the equivalent block_/comment_*_string parameters)');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('42291df6-4b46-402e-9d1d-f18ce9c68281', '64c26096-e3e3-4664-8e9c-4ad5f5dab153', 2, 'backup and validate');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4edae7ec-0a8a-4f74-ab26-6aef140b4ad5', '64c26096-e3e3-4664-8e9c-4ad5f5dab153', 3, 'src and dest');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('696c7100-dbc5-4a66-a9cb-c6bcce58c11d', '4c19187d-3023-473b-a09f-a5835688b4ea', 0, 'template only works on Linux managed nodes; copy works on any OS');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('60a9b477-9673-4041-8a85-82c9e2165eb6', '4c19187d-3023-473b-a09f-a5835688b4ea', 1, 'template renders its src through the Jinja2 engine (evaluating variables/filters/control structures) before writing dest; copy transfers src''s bytes as-is with no rendering');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('53586b34-da75-4696-8f11-ebb04062eca3', '4c19187d-3023-473b-a09f-a5835688b4ea', 2, 'copy can only copy directories, template can only copy single files');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('739757a6-99c6-419b-b2ec-524042c8c2f1', '4c19187d-3023-473b-a09f-a5835688b4ea', 3, 'There is no real difference; they are interchangeable in every case');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2e557a37-b346-408a-adbe-5d2bbe9d5ba6', 'be3b3088-dbaa-4f54-9bd1-e69fd1471e8c', 0, 'template, since it always produces more reliable output');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('067c120d-dc21-4ae7-a7fe-f9e10b1836ae', 'be3b3088-dbaa-4f54-9bd1-e69fd1471e8c', 1, 'copy, since the file needs to be transferred as-is without any Jinja2 processing');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e12e1dcb-478b-4ed2-856e-2cb1aa637b91', 'be3b3088-dbaa-4f54-9bd1-e69fd1471e8c', 2, 'Either works identically for this case');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('19949cd3-59d3-4218-a7f6-3460f5f4cf78', 'be3b3088-dbaa-4f54-9bd1-e69fd1471e8c', 3, 'Neither; only the file module can deliver static content');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('654076de-c86c-4446-8a0f-59823cb0cc8a', '49749ba6-d27b-49cd-ba08-4abed5631c47', 0, './templates/');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cbe04863-ea00-4601-8506-c2f47d100dc6', '49749ba6-d27b-49cd-ba08-4abed5631c47', 1, './files/');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4f84bc93-4c3d-4b7b-8214-3161ca81640f', '49749ba6-d27b-49cd-ba08-4abed5631c47', 2, './copies/');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89479f26-ffbe-4463-9986-eb325bff617a', '49749ba6-d27b-49cd-ba08-4abed5631c47', 3, './static/');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('93f11a3b-021e-4c6f-b0b8-4174cf971061', '60115d40-1626-452f-80c2-88d0a5322396', 0, 'It is functionally identical to the template module and also writes a file to the managed node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('df4992e2-fca0-4a56-93aa-1181ae6c40b4', '60115d40-1626-452f-80c2-88d0a5322396', 1, 'It renders the Jinja2 template on the CONTROL NODE and returns the rendered content as a string/variable for use elsewhere in the play — it does not write anything to the managed node by itself');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d09c3c08-2d14-4b16-8529-4fe299568070', '60115d40-1626-452f-80c2-88d0a5322396', 2, 'It only works for templates already deployed to a managed node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6efa301-4547-40f4-af40-6858309fb88f', '60115d40-1626-452f-80c2-88d0a5322396', 3, 'It requires root privileges on the managed node to execute');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('067fcf44-951d-4815-9e85-28450126c495', '76469ff6-4980-455e-ad7e-efc6d5eac2f1', 0, 'When the goal is simply to place a rendered config file at a fixed path on a managed node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a7693ddf-77dc-4b03-84d7-9e6488390597', '76469ff6-4980-455e-ad7e-efc6d5eac2f1', 1, 'When the rendered content needs to be used as an input value to another task (e.g. passed into a uri module''s body, or set as a variable for later use) rather than written directly to a file on the managed node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11c540ce-7496-4bd5-b87d-4083281e7edd', '76469ff6-4980-455e-ad7e-efc6d5eac2f1', 2, 'When the file must never be re-rendered on subsequent runs');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5755d22f-d642-4e96-90a5-a761ece217a4', '76469ff6-4980-455e-ad7e-efc6d5eac2f1', 3, 'When mode/validate parameters are required, since the module doesn''t support them');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98e00884-8d5c-41e4-8e6f-69fd49c6fb45', '63f261dd-8a35-4862-b7a1-62fe1d338b83', 0, 'Use the template module twice, once for each destination');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f1941cfe-7969-4a08-a6ef-d71bf02f49d7', '63f261dd-8a35-4862-b7a1-62fe1d338b83', 1, 'Use `lookup(''template'', ...)` to render the content once into a variable, then use that variable both in the `uri` module''s body and in a `copy` (with `content:`) or subsequent task that writes it to the managed node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e292655b-d11f-4b41-95ac-0f3d1e4ee393', '63f261dd-8a35-4862-b7a1-62fe1d338b83', 2, 'This is not achievable with Ansible; the content must be manually duplicated in two separate .j2 files');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('888269a9-790a-47d1-9bff-677dc2cf7268', '63f261dd-8a35-4862-b7a1-62fe1d338b83', 3, 'Use copy for both destinations, since copy can also do Jinja2 rendering');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('096aeb65-a9ec-4da2-9adf-e4a88475d53a', '77c6ea84-4a4e-4b5f-af1a-11c3ef6f669f', 0, 'On the managed node, after the raw .j2 file is copied over');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b647cb8a-c99a-484d-927e-d270747eb0bd', '77c6ea84-4a4e-4b5f-af1a-11c3ef6f669f', 1, 'On the Ansible control node — Ansible always renders Jinja2 templates locally before anything is transferred to or acted on for the managed node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6d04f58b-7a8b-48b1-bfd0-a8e8a139575c', '77c6ea84-4a4e-4b5f-af1a-11c3ef6f669f', 2, 'It varies: the module renders on the managed node, the lookup renders on the control node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4dc5cbc2-8116-40a4-ac8e-3aa160b50842', '77c6ea84-4a4e-4b5f-af1a-11c3ef6f669f', 3, 'Rendering happens on whichever host has more available memory at runtime');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d5cadba-5846-490c-8717-03a0134155dc', 'd527b68a-1d10-4585-8f14-78967d6ce07e', 0, 'Nothing special — this works even if fact gathering was disabled for the play');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('940b2a98-b31f-449e-85f0-9e3e7da10f13', 'd527b68a-1d10-4585-8f14-78967d6ce07e', 1, 'Fact gathering (gather_facts, or an explicit setup task) must have run for that host beforehand so ansible_facts is actually populated, otherwise the key lookup fails or the reference resolves to undefined');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1cb07d09-caef-48e6-bbe3-7027c74d1a62', 'd527b68a-1d10-4585-8f14-78967d6ce07e', 2, 'The template module automatically gathers facts on demand whenever a fact is referenced');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c87015dd-ee29-42dd-b063-6e742a76ba7d', 'd527b68a-1d10-4585-8f14-78967d6ce07e', 3, 'ansible_facts can only be referenced inside {% if %} blocks, never inside {{ }} interpolation');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e8150a31-9bfd-41e0-9e32-5a3572632fd6', '11cf3b2c-8242-4745-acfe-e331f902aa96', 0, 'It silently renders as an empty string with no error');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('035fbe2d-6b6c-45c7-a5f9-d05dcb9de0aa', '11cf3b2c-8242-4745-acfe-e331f902aa96', 1, 'The task fails with an ''undefined variable'' templating error, and dest is not written');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c0f22855-d156-4f85-a9c0-ddf870cf7afd', '11cf3b2c-8242-4745-acfe-e331f902aa96', 2, 'Ansible automatically substitutes the variable''s name as a placeholder string');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a19564d5-4be4-4c1a-a8e4-819fab103b51', '11cf3b2c-8242-4745-acfe-e331f902aa96', 3, 'It renders successfully but logs a deprecation warning');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c3fa2e39-6927-43a3-a233-6c834aa09472', '2fc9c9f1-fd80-4bb3-8c36-1b3d609515b3', 0, 'There is no way to preview rendered output before an actual managed-node run');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff3ffed0-2177-4636-9a19-ce82a308362e', '2fc9c9f1-fd80-4bb3-8c36-1b3d609515b3', 1, 'Use `ansible-playbook --check --diff` (or the template lookup plugin in a debug task) to see the would-be rendered content/diff without committing changes to the managed node');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('87ac701c-2333-4300-85c1-e9f39996edfa', '2fc9c9f1-fd80-4bb3-8c36-1b3d609515b3', 2, 'Only Molecule test suites can preview template output');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('73e30a10-871b-4877-985a-76f4700a773a', '2fc9c9f1-fd80-4bb3-8c36-1b3d609515b3', 3, 'Manually copy the .j2 file and interpret the Jinja2 syntax by hand');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3b38e8db-b0b4-422b-b21b-a286bd66f0a9', '8906bc85-a463-4980-88f6-200604620ce3', 0, 'Always from the play''s top-level playbook directory, ignoring the role entirely');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9ab49396-ae55-4855-86e4-941c4b681e17', '8906bc85-a463-4980-88f6-200604620ce3', 1, 'From the role''s own templates/ directory, following normal Ansible role/collection path-search rules — the same convention applies whether the role lives standalone or inside a collection');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('86ba0f84-3fac-4848-a44f-163749a3527e', '8906bc85-a463-4980-88f6-200604620ce3', 2, 'It cannot resolve relative paths when the role is inside a collection; only absolute paths work');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('63b600b9-424f-4b5a-b603-e69a88255ff4', '8906bc85-a463-4980-88f6-200604620ce3', 3, 'From a shared, single templates/ directory at the collection''s root only');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
INSERT INTO questions (id, paper_id, sort_order, question_text, subject, topic, answer_type)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('719c7363-cd4b-4a94-9c6c-bbe097061ea4', '6e0d26df-ed0b-4730-a5bf-69de2bb8cb15', 0, 'The task reports ''changed'' both times, since template always rewrites the file');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('698729ea-ed6b-4a15-9469-ae75c5efc8dc', '6e0d26df-ed0b-4730-a5bf-69de2bb8cb15', 1, 'The task reports ''ok'' (no change) on the second run, since the freshly rendered content matches what''s already at dest — template is idempotent');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d15c8b4b-8693-43da-9311-cca2cc02f48c', '6e0d26df-ed0b-4730-a5bf-69de2bb8cb15', 2, 'The second run always fails because dest already exists');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('475e690b-8bd5-4a2e-acda-6ec024df0996', '6e0d26df-ed0b-4730-a5bf-69de2bb8cb15', 3, 'Idempotency only applies if force: false is set');
INSERT INTO question_answers (question_id, correct_option_id, explanation, source_note)
