-- ---------- Paper ----------
VALUES ('f237447c-84a4-4694-a28d-fa193ebf0335', 'rhce-jinja2-templates', 'RHCE Ansible Practice: Jinja2 Templates & the template Module', 'ansible', ARRAY['RHCE', 'EX294', 'Jinja2', 'template module', 'Templating', 'Filters']::TEXT[], 35, 'advanced', true, 6, 60, 1, 0);

-- ── Section: Jinja2 Syntax Fundamentals (12 questions) — Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2's own template-designer documentation and Ansible's playbook-filters user guide; verified via web search 2026-09-04. ──

VALUES ('e8e419fd-275e-4e3f-98af-a5ea73702cc3', 'f237447c-84a4-4694-a28d-fa193ebf0335', 1, 'Inside a .j2 template file, how is an Ansible variable named `app_port` interpolated into the rendered output?', 'Ansible', 'Variable Interpolation', 'mcq');
VALUES ('e8e419fd-275e-4e3f-98af-a5ea73702cc3', '532777d6-2289-4526-9602-ffa7cf2e82ff', 'Jinja2 variable interpolation uses double curly braces, {{ app_port }} — {% %} is reserved for statements/control structures, not value interpolation.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('60bde359-df84-46d6-9279-962d8af7fa57', 'f237447c-84a4-4694-a28d-fa193ebf0335', 2, 'Which delimiter pair encloses Jinja2 control-flow statements like `if` and `for` inside a template, by default?', 'Ansible', 'Statement Delimiters', 'mcq');
VALUES ('60bde359-df84-46d6-9279-962d8af7fa57', '085f3faa-2d64-4ea4-b2b5-8f4ff78fa44c', '{% %} encloses statements (if/for/set/etc.); {{ }} is for expressions/output, and {# #} is for comments (stripped from output).', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('08989226-4670-47c8-9632-eb3139af088d', 'f237447c-84a4-4694-a28d-fa193ebf0335', 3, 'How are comments written inside a Jinja2 template so they never appear in the rendered output?', 'Ansible', 'Comments', 'mcq');
VALUES ('08989226-4670-47c8-9632-eb3139af088d', '01049657-7dae-4fad-9017-d95e9e68aa3a', '{# ... #} is the Jinja2 comment delimiter; content inside it is stripped entirely from the rendered output.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('092ede84-f319-45a6-9d31-a2c7d173c53f', 'f237447c-84a4-4694-a28d-fa193ebf0335', 4, 'What does `{{ retry_count | default(3) }}` render as if the `retry_count` variable is undefined?', 'Ansible', 'The default Filter', 'mcq');
VALUES ('092ede84-f319-45a6-9d31-a2c7d173c53f', '8ca721a5-bc31-4082-9dfc-08d490e7eda3', 'The default filter substitutes its argument (3) when the piped variable is undefined, avoiding an ''undefined variable'' failure.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('52fbb497-adc3-430b-b2c1-ba1c8b5a806a', 'f237447c-84a4-4694-a28d-fa193ebf0335', 5, 'Given `myvar` is explicitly set to an empty string `""`, what does `{{ myvar | default(''fallback'') }}` render as, and why?', 'Ansible', 'default with Falsy Values', 'mcq');
VALUES ('52fbb497-adc3-430b-b2c1-ba1c8b5a806a', '34a53fd0-9dea-4c4a-bb54-e08476b55ec9', 'By default, Jinja2''s default filter only substitutes for undefined variables; to also treat falsy defined values (empty string, 0, False) as needing the fallback, you must pass a second argument: default(''fallback'', true).', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('374cf0cf-ce07-4355-98a4-3a1c8b1dd311', 'f237447c-84a4-4694-a28d-fa193ebf0335', 6, 'Given `servers = [''web1'', ''web2'', ''web3'']`, what does `{{ servers | join('', '') }}` render as?', 'Ansible', 'The join Filter', 'mcq');
VALUES ('374cf0cf-ce07-4355-98a4-3a1c8b1dd311', '5d2ecf93-03be-4e16-8a52-3df32046f2a7', 'join('', '') concatenates the list''s elements into a single string separated by the given delimiter: ''web1, web2, web3''.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('1381b5a7-2f65-4ab2-a229-5d602a7ea49b', 'f237447c-84a4-4694-a28d-fa193ebf0335', 7, 'What does `{{ config_dict | to_json }}` do to a Jinja2/Python dictionary variable `config_dict`?', 'Ansible', 'The to_json Filter', 'mcq');
VALUES ('1381b5a7-2f65-4ab2-a229-5d602a7ea49b', 'e378b9e2-f5a4-4875-b72a-1fe132a43355', 'to_json serializes the piped data structure into a JSON string (compact, single-line by default); to_nice_json produces an indented, pretty-printed variant.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('c821455d-1b41-4ef1-b24f-673c802313fb', 'f237447c-84a4-4694-a28d-fa193ebf0335', 8, 'Which is valid Jinja2 syntax for a conditional block inside a template that outputs ''enabled'' only when `feature_flag` is true?', 'Ansible', 'if Control Structure', 'mcq');
VALUES ('c821455d-1b41-4ef1-b24f-673c802313fb', 'cde2ed47-185d-45d4-a67e-75d94fd3fdc3', 'Control structures use the statement delimiters {% %}, with a matching {% endif %} closing the block.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('89090488-e480-4702-be68-fc12fc98f617', 'f237447c-84a4-4694-a28d-fa193ebf0335', 9, 'Which snippet correctly iterates over a list variable `users` inside a Jinja2 template, outputting each username on its own line?', 'Ansible', 'for Loop Control Structure', 'mcq');
VALUES ('89090488-e480-4702-be68-fc12fc98f617', 'f507fd1c-73b0-4c8d-b44b-3ec9bfe5c2f9', 'Jinja2''s loop syntax is {% for x in iterable %} ... {% endfor %} — ''foreach''/''loop'' are not Jinja2 keywords.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('9ad4fb91-76d3-42fd-8ced-186e62ce72bc', 'f237447c-84a4-4694-a28d-fa193ebf0335', 10, 'Inside a Jinja2 `{% for %}` loop, what does the built-in `loop.index` variable provide?', 'Ansible', 'Loop Variable: loop.index', 'mcq');
VALUES ('9ad4fb91-76d3-42fd-8ced-186e62ce72bc', '469a2d3e-adf2-4c4d-b78c-e6ca2046e33b', 'loop.index is 1-based (loop.index0 is the zero-based equivalent) — a common point of confusion worth memorizing distinctly.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('6664b01f-1a94-4dd9-9e9c-0fbc43257b9b', 'f237447c-84a4-4694-a28d-fa193ebf0335', 11, 'In Jinja2, what is the syntactic and conceptual difference between a filter (e.g. `| default(...)`) and a test (e.g. `is defined`)?', 'Ansible', 'Filters vs. Tests', 'mcq');
VALUES ('6664b01f-1a94-4dd9-9e9c-0fbc43257b9b', 'c484bcf6-5284-46a0-8cc4-e083c22a4a11', 'Filters (pipe syntax) transform/format a value for output; tests (is syntax) answer a yes/no question about a value, most commonly inside {% if %} conditions — e.g. {% if myvar is defined %} vs. {{ myvar | default(''x'') }}.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

VALUES ('e1d984b8-1935-4852-a6be-ba427ce66c18', 'f237447c-84a4-4694-a28d-fa193ebf0335', 12, 'What do the `trim_blocks` and `lstrip_blocks` Jinja2 environment options control (both configurable as template module parameters)?', 'Ansible', 'Whitespace Control', 'mcq');
VALUES ('e1d984b8-1935-4852-a6be-ba427ce66c18', '1b760b98-e8ca-4e92-b3c2-d1a63e151699', 'These two settings exist specifically to keep {% %} block tags from leaving stray blank lines/leading whitespace in rendered output — trim_blocks removes the trailing newline after a block tag, lstrip_blocks strips leading whitespace before one.', 'Jinja2 syntax in Ansible templates — variable interpolation, filters, control structures — authored from Jinja2''s own template-designer documentation and Ansible''s playbook-filters user guide; verified via web search 2026-09-04.');

-- ── Section: The template Module (11 questions) — The template module's parameters and behavior — authored from docs.ansible.com's ansible.builtin.template module documentation; verified via web search 2026-09-04. ──

VALUES ('0d1b7efc-b379-4a14-a639-54ac1c5879f0', 'f237447c-84a4-4694-a28d-fa193ebf0335', 13, 'Which two parameters are required for the `ansible.builtin.template` module?', 'Ansible', 'Required Parameters', 'mcq');
VALUES ('0d1b7efc-b379-4a14-a639-54ac1c5879f0', 'dd3c6b5d-028d-4552-a267-ef7f8f54abf5', 'src (the Jinja2 template on the control node) and dest (where to render it on the managed node) are the module''s required parameters.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('bc426b1c-a2d6-4614-a6c0-b012d3456afa', 'f237447c-84a4-4694-a28d-fa193ebf0335', 14, 'If `src: nginx.conf.j2` is given as a relative path, where does the template module look for that file by convention?', 'Ansible', 'src Resolution', 'mcq');
VALUES ('bc426b1c-a2d6-4614-a6c0-b012d3456afa', 'bf040a5f-051d-4a9d-b2ee-6ec07cd62144', 'template resolves a relative src from a ./templates/ directory by convention (paralleling copy''s ./files/ convention for its own src).', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('f43b34e4-c531-4bb7-a654-997cf09fdc7e', 'f237447c-84a4-4694-a28d-fa193ebf0335', 15, 'If the `mode` parameter is omitted when using template to create a brand-new file that doesn''t yet exist at dest, what permission does the resulting file get?', 'Ansible', 'mode Parameter', 'mcq');
VALUES ('f43b34e4-c531-4bb7-a654-997cf09fdc7e', '23c40243-1ffa-4197-9083-da6b850c8782', 'Without an explicit mode, Ansible falls back to the destination system''s default umask for a newly created file; an already-existing dest instead keeps its current permissions if mode isn''t specified.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('5916b803-9dd5-4844-9823-92c9bc9c0760', 'f237447c-84a4-4694-a28d-fa193ebf0335', 16, 'What does setting `backup: true` on a template task do?', 'Ansible', 'backup Parameter', 'mcq');
VALUES ('5916b803-9dd5-4844-9823-92c9bc9c0760', 'ea49d365-fba7-49a0-b960-8357e9c94c1c', 'backup: true makes a timestamped backup of the file already at dest before template overwrites it — a safety net for recovering the prior version.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('af016e2c-7159-4bbc-bc06-a8a4a4bddca5', 'f237447c-84a4-4694-a28d-fa193ebf0335', 17, 'With `force: false` on a template task, what happens if dest already exists with content different from what would be rendered?', 'Ansible', 'force Parameter', 'mcq');
VALUES ('af016e2c-7159-4bbc-bc06-a8a4a4bddca5', '96108da7-1ecf-46bc-8fea-fabaaa0d031d', 'force defaults to true (overwrite differing content); setting it to false means the file is only written if dest doesn''t already exist, leaving an existing file with different content untouched.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('a757c7ed-8040-422c-9f8b-0206e5ce204c', 'f237447c-84a4-4694-a28d-fa193ebf0335', 18, 'A task uses `validate: ''sshd -t -f %s''` on a template module call rendering a new sshd_config. What must be true about the `%s` in that string?', 'Ansible', 'validate Parameter Syntax', 'mcq');
VALUES ('a757c7ed-8040-422c-9f8b-0206e5ce204c', 'b63a21bf-7ce3-40ff-9a51-f0eed0836623', 'validate''s command string must contain %s, which Ansible replaces with the path to the rendered-but-not-yet-moved temp file, so the validation command checks the actual new content before it''s put into place.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('0d12515b-2b31-47ab-b2e0-7aa46c7998de', 'f237447c-84a4-4694-a28d-fa193ebf0335', 19, 'If the command given to `validate` exits with a non-zero status, what happens to dest?', 'Ansible', 'validate Failure Behavior', 'mcq');
VALUES ('0d12515b-2b31-47ab-b2e0-7aa46c7998de', '0b154799-6736-42db-ab45-e7fd605adc1f', 'A non-zero exit from the validate command fails the task and prevents the (invalid) rendered file from ever being moved into place at dest — the whole point of using validate.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('274aa5df-d415-4092-8772-da1b4d527e4c', 'f237447c-84a4-4694-a28d-fa193ebf0335', 20, 'Why is `validate` commonly used with templates that render files like /etc/sudoers or sshd_config specifically?', 'Ansible', 'Typical validate Use Cases', 'mcq');
VALUES ('274aa5df-d415-4092-8772-da1b4d527e4c', '60e39e1e-84c7-46cd-9921-bec44579dd2b', 'sudoers and sshd_config are exactly the kind of file where a broken syntax could lock out sudo access or prevent sshd from starting/reloading — validate lets their own native syntax-checker catch mistakes before the real file is touched.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('f896c2be-6ffe-4c48-a225-89c7b1ca09c8', 'f237447c-84a4-4694-a28d-fa193ebf0335', 21, 'What does the `follow` parameter control on the template module?', 'Ansible', 'follow Parameter', 'mcq');
VALUES ('f896c2be-6ffe-4c48-a225-89c7b1ca09c8', '36f68ac5-682a-4bbb-b4cd-377589d3fed8', 'follow controls symlink handling: true means the module writes through an existing symlink at dest to its target file; false (the default) means it operates on dest as-is (e.g. replacing the symlink itself).', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('ca8574ff-bf4c-4315-bf82-5aea4d831c68', 'f237447c-84a4-4694-a28d-fa193ebf0335', 22, 'What is the purpose of the `output_encoding` parameter on the template module?', 'Ansible', 'output_encoding Parameter', 'mcq');
VALUES ('ca8574ff-bf4c-4315-bf82-5aea4d831c68', '0dab9299-d316-43d4-a2b1-f118169d567f', 'src templates are always read as UTF-8, but output_encoding (default utf-8) controls the encoding used when writing the rendered destination file, letting it differ from the source''s encoding if needed.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

VALUES ('64c26096-e3e3-4664-8e9c-4ad5f5dab153', 'f237447c-84a4-4694-a28d-fa193ebf0335', 23, 'A legacy config file already uses literal `{{` and `}}` characters as part of its own syntax (unrelated to Jinja2), which would otherwise conflict with Jinja2 variable interpolation when templated. Which template module parameters exist specifically to work around exactly this kind of conflict?', 'Ansible', 'Custom Delimiter Parameters', 'mcq');
VALUES ('64c26096-e3e3-4664-8e9c-4ad5f5dab153', 'ee9e67fa-9c59-42d8-8c9c-c00ae5becf89', 'The module exposes Jinja2''s delimiter-override parameters (variable_start_string/variable_end_string, block_start_string/block_end_string, comment_start_string/comment_end_string) precisely so a template''s own required literal syntax doesn''t collide with Jinja2''s default {{ }}/{% %} markers.', 'The template module''s parameters and behavior — authored from docs.ansible.com''s ansible.builtin.template module documentation; verified via web search 2026-09-04.');

-- ── Section: template vs. copy & the template Lookup Plugin (12 questions) — template vs. copy and the template lookup plugin — authored from docs.ansible.com's module/lookup documentation; verified via web search 2026-09-04. ──

VALUES ('4c19187d-3023-473b-a09f-a5835688b4ea', 'f237447c-84a4-4694-a28d-fa193ebf0335', 24, 'What is the fundamental difference in behavior between the `template` module and the `copy` module?', 'Ansible', 'Core Distinction', 'mcq');
VALUES ('4c19187d-3023-473b-a09f-a5835688b4ea', '60a9b477-9673-4041-8a85-82c9e2165eb6', 'The defining difference is rendering: template processes src as a Jinja2 template (variables, filters, {% %} logic all evaluated) before writing the result; copy is a byte-for-byte transfer with no templating applied.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('be3b3088-dbaa-4f54-9bd1-e69fd1471e8c', 'f237447c-84a4-4694-a28d-fa193ebf0335', 25, 'A task needs to deliver a static binary configuration file that must be placed on managed nodes completely unmodified, with no variable substitution. Which module is the correct choice?', 'Ansible', 'Choosing template vs. copy', 'mcq');
VALUES ('be3b3088-dbaa-4f54-9bd1-e69fd1471e8c', '067c120d-dc21-4ae7-a7fe-f9e10b1836ae', 'For content that must not be altered/rendered, copy is correct; using template on non-Jinja2 content risks the engine misinterpreting stray {{ or {% sequences that happen to appear in the file.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('49749ba6-d27b-49cd-ba08-4abed5631c47', 'f237447c-84a4-4694-a28d-fa193ebf0335', 26, 'Paralleling template''s ./templates/ convention, where does the copy module look for a relative src path by convention?', 'Ansible', 'copy''s src Convention', 'mcq');
VALUES ('49749ba6-d27b-49cd-ba08-4abed5631c47', 'cbe04863-ea00-4601-8506-c2f47d100dc6', 'copy resolves a relative src from a ./files/ directory by convention, distinct from template''s ./templates/ convention.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('60115d40-1626-452f-80c2-88d0a5322396', 'f237447c-84a4-4694-a28d-fa193ebf0335', 27, 'What does `{{ lookup(''template'', ''snippet.j2'') }}` do, as opposed to using the template MODULE on the same file?', 'Ansible', 'template Lookup Plugin Behavior', 'mcq');
VALUES ('60115d40-1626-452f-80c2-88d0a5322396', 'df4992e2-fca0-4a56-93aa-1181ae6c40b4', 'The template lookup plugin renders on the control node and hands back a string value — useful for embedding rendered content into another variable or module argument — whereas the template module renders AND writes the result as a file on the managed node in one step.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('76469ff6-4980-455e-ad7e-efc6d5eac2f1', 'f237447c-84a4-4694-a28d-fa193ebf0335', 28, 'In which scenario would `lookup(''template'', ...)` be the better choice over the template module?', 'Ansible', 'When to Use the Lookup Instead of the Module', 'mcq');
VALUES ('76469ff6-4980-455e-ad7e-efc6d5eac2f1', 'a7693ddf-77dc-4b03-84d7-9e6488390597', 'The lookup plugin is the right tool when you need the rendered text as data to feed into something else in the play (an API call body, a variable, a debug message) rather than a file drop on the managed node — that specific use case is what the module can''t do directly.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('63f261dd-8a35-4862-b7a1-62fe1d338b83', 'f237447c-84a4-4694-a28d-fa193ebf0335', 29, 'A playbook needs the exact same rendered Jinja2 content both written to a file on the managed node AND embedded inline inside a separate API request body sent via the `uri` module. What combination best achieves this without rendering the template twice with duplicated logic?', 'Ansible', 'Multiple Files vs. Reusable Content', 'mcq');
VALUES ('63f261dd-8a35-4862-b7a1-62fe1d338b83', 'f1941cfe-7969-4a08-a6ef-d71bf02f49d7', 'Rendering once via the lookup into a variable, then reusing that rendered string both in the uri module''s body and via copy''s content parameter (or another mechanism) avoids re-rendering the same Jinja2 logic twice and keeps a single source of truth.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('77c6ea84-4a4e-4b5f-af1a-11c3ef6f669f', 'f237447c-84a4-4694-a28d-fa193ebf0335', 30, 'Both the template module and the template lookup plugin use the Jinja2 engine. Where does Jinja2 rendering actually happen in both cases?', 'Ansible', 'Templating on the Control Node vs. Managed Node', 'mcq');
VALUES ('77c6ea84-4a4e-4b5f-af1a-11c3ef6f669f', 'b647cb8a-c99a-484d-927e-d270747eb0bd', 'Ansible renders Jinja2 templates on the control node in both cases; the template module then transfers the already-rendered result to dest on the managed node, while the lookup plugin simply returns the rendered string to the control-node play without any managed-node transfer step of its own.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('d527b68a-1d10-4585-8f14-78967d6ce07e', 'f237447c-84a4-4694-a28d-fa193ebf0335', 31, 'A Jinja2 template references `{{ ansible_facts[''default_ipv4''][''address''] }}` to embed a managed node''s IP address into a rendered config file. What must be true for this to work correctly?', 'Ansible', 'Templates and Ansible Facts', 'mcq');
VALUES ('d527b68a-1d10-4585-8f14-78967d6ce07e', '940b2a98-b31f-449e-85f0-9e3e7da10f13', 'Referencing ansible_facts requires that facts were actually gathered for the host earlier in the play (gather_facts: true is the default, but it can be disabled) — without that, the referenced key won''t be populated.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('11cf3b2c-8242-4745-acfe-e331f902aa96', 'f237447c-84a4-4694-a28d-fa193ebf0335', 32, 'If a Jinja2 template references a variable that is undefined and has no `default()` filter applied, what happens when the template module tries to render it?', 'Ansible', 'Rendering Failures', 'mcq');
VALUES ('11cf3b2c-8242-4745-acfe-e331f902aa96', '035fbe2d-6b6c-45c7-a5f9-d05dcb9de0aa', 'By default, referencing an undefined variable in a Jinja2 expression raises a templating error that fails the task (unless a default filter or an `is defined` test guards it), and the file at dest is not written.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('2fc9c9f1-fd80-4bb3-8c36-1b3d609515b3', 'f237447c-84a4-4694-a28d-fa193ebf0335', 33, 'Before actually running a template task against production, which practical technique lets you preview exactly what a .j2 file would render to, using the variables that would apply to a given host?', 'Ansible', 'Debugging Template Output', 'mcq');
VALUES ('2fc9c9f1-fd80-4bb3-8c36-1b3d609515b3', 'ff3ffed0-2177-4636-9a19-ce82a308362e', '--check --diff shows what the template module would change (a content diff) without applying it, and using the template lookup in a debug task is another common way to preview exactly what a given host''s variables would render to.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('8906bc85-a463-4980-88f6-200604620ce3', 'f237447c-84a4-4694-a28d-fa193ebf0335', 34, 'A role references `src: templates/app.conf.j2` while the role itself is shipped inside a Content Collection alongside other roles. Where does template resolve that relative src from?', 'Ansible', 'Templates Sourced From a Collection', 'mcq');
VALUES ('8906bc85-a463-4980-88f6-200604620ce3', '9ab49396-ae55-4855-86e4-941c4b681e17', 'Standard Ansible role path-search rules apply regardless of whether the role is standalone or packaged inside a collection — a relative src resolves against the calling role''s own templates/ directory.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');

VALUES ('6e0d26df-ed0b-4730-a5bf-69de2bb8cb15', 'f237447c-84a4-4694-a28d-fa193ebf0335', 35, 'Running the same template task twice in a row against a host where the rendered content hasn''t changed produces what result on the second run?', 'Ansible', 'Idempotency of template', 'mcq');
VALUES ('6e0d26df-ed0b-4730-a5bf-69de2bb8cb15', '698729ea-ed6b-4a15-9469-ae75c5efc8dc', 'template compares the freshly rendered content against what''s currently at dest; if they match, no write occurs and the task reports unchanged (''ok'') — this idempotency is core to how Ansible tasks are expected to behave on repeat runs.', 'template vs. copy and the template lookup plugin — authored from docs.ansible.com''s module/lookup documentation; verified via web search 2026-09-04.');
